const fs = require('fs');
const path = require('path');
const vaultPath = '/home/node/.n8n/obsidian';
const input = $input.first().json;

const foldersToSearch = input.output?.folders || input.folders || ['Inbox'];
const action = input.output?.action || input.action || 'chat';
const noteTitle = input.output?.note_title || input.note_title || '';
const isAudio = $('Code Titulos').item.json.isAudio || false;

// Recuperar el texto del usuario desde Code Titulos
const userMessage = $('Code Titulos').item.json.text || 
                    $('Code Titulos').item.json.message && $('Code Titulos').item.json.message.text || '';

let context = '';
let allTitles = [];

const allFolders = ['Inbox', 'Proyectos', 'Diario', 'Contactos', 'Finanzas', 'Aprendizaje', 'Sistema_Otto'];

for (const folder of allFolders) {
  try {
    const files = fs.readdirSync(path.join(vaultPath, folder));
    for (const file of files) {
      if (file.endsWith('.md') && !file.includes('Index')) {
        allTitles.push(`[${folder}] ${file.replace('.md', '')}`);
      }
    }
  } catch(e) {}
}

if (action === 'read' && noteTitle && noteTitle.length > 0) {
  const titles = noteTitle.split(',').map(t => t.trim());
  for (const t of titles) {
    for (const folder of allFolders) {
      const notePath = path.join(vaultPath, folder, `${t}.md`);
      try {
        const content = fs.readFileSync(notePath, 'utf8');
        context += `--- [${folder}] ${t}.md ---\n${content}\n\n`;
        break;
      } catch(e) {}
    }
  }
  context = context || `No se encontraron las notas: ${noteTitle}`;

} else if (action === 'list') {
  for (const folder of foldersToSearch) {
    const folderPath = path.join(vaultPath, folder);
    try {
      const files = fs.readdirSync(folderPath);
      const notes = files
        .filter(f => f.endsWith('.md') && !f.includes('Index'))
        .map(f => f.replace('.md', ''));
      if (notes.length > 0) {
        context += `[${folder}]: ${notes.join(', ')}\n`;
      }
    } catch(e) {}
  }
  context = context || 'No hay notas en esas carpetas.';

} else if (action === 'edit' && noteTitle && noteTitle.length > 0) {
  for (const folder of allFolders) {
    const notePath = path.join(vaultPath, folder, `${noteTitle}.md`);
    try {
      const content = fs.readFileSync(notePath, 'utf8');
      context = `--- [${folder}] ${noteTitle}.md ---\n${content}`;
      break;
    } catch(e) {}
  }
  context = context || `No se encontro la nota "${noteTitle}".`;

} else if (action === 'delete' && noteTitle && noteTitle.length > 0) {
  context = `Nota a eliminar: ${noteTitle}`;

} else {
  context = 'Sin notas relevantes para esta accion.';
}

return [{
  json: {
    ...input,
    context,
    allTitles: allTitles.join('\n'),
    action,
    isAudio,
    message: input.message,
    userMessage
  }
}];

const input = $input.first().json;

let data;
try {
  data = JSON.parse(input.output);
} catch(e) {
  try {
    const cleaned = input.output
      .replace(/[\u0000-\u001F\u007F-\u009F]/g, ' ')
      .replace(/```json|```/g, '')
      .trim();
    data = JSON.parse(cleaned);
  } catch(e2) {
    data = { reply: input.output, is_note: false, action: 'none' };
  }
}

const is_note = data.is_note === true;
