const fs = require('fs');
const path = require('path');
const item = $input.first().json;
const vaultPath = '/home/node/.n8n/obsidian';
const historialPath = '/home/node/.n8n/obsidian/.historial.json';

const folder = item.folder || 'Inbox';
const title = item.title || 'Nota sin titulo';
const body = item.body || '';
const action = item.action || 'create';

const notePath = path.join(vaultPath, folder, `${title}.md`);
const indexPath = path.join(vaultPath, folder, `${folder} Index.md`);

function updateIndex(indexFile, noteTitle, add) {
  let content = '';
  try {
    content = fs.readFileSync(indexFile, 'utf8');
  } catch(e) {
    content = `# ${folder} Index\n`;
  }
  const link = `- [[${noteTitle}]]`;
  if (add && !content.includes(link)) {
    content = content.trimEnd() + `\n${link}`;
  } else if (!add) {
    content = content.split('\n').filter(l => l !== link).join('\n');
  }
  fs.writeFileSync(indexFile, content);
}

function removeLinksFromVault(noteTitle) {
  const allFolders = ['Inbox', 'Proyectos', 'Diario', 'Contactos', 'Finanzas', 'Aprendizaje', 'Sistema_Otto'];
  const linkPattern = new RegExp(`\\[\\[${noteTitle}\\]\\]`, 'g');
  for (const f of allFolders) {
    try {
      const files = fs.readdirSync(path.join(vaultPath, f));
      for (const file of files) {
        if (file.endsWith('.md')) {
          const filePath = path.join(vaultPath, f, file);
          let content = fs.readFileSync(filePath, 'utf8');
          if (linkPattern.test(content)) {
            content = content.replace(linkPattern, noteTitle);
            fs.writeFileSync(filePath, content);
          }
        }
      }
    } catch(e) {}
  }
}

if (action === 'create' || action === 'edit') {
  const dir = path.join(vaultPath, folder);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(notePath, body);
  if (action === 'create') {
    updateIndex(indexPath, title, true);
  }

} else if (action === 'delete') {
  try {
    // Buscar la nota en todas las carpetas
    const allFolders = ['Inbox', 'Proyectos', 'Diario', 'Contactos', 'Finanzas', 'Aprendizaje', 'Sistema_Otto'];
    let deleted = false;
    for (const f of allFolders) {
      const fp = path.join(vaultPath, f, `${title}.md`);
      if (fs.existsSync(fp)) {
        fs.unlinkSync(fp);
        const idx = path.join(vaultPath, f, `${f} Index.md`);
        updateIndex(idx, title, false);
        deleted = true;
        break;
      }
    }
    if (deleted) {
      removeLinksFromVault(title);
    }
  } catch(e) {}
}

// Guardar historial global
