const fs = require('fs');
const path = require('path');

const historialPath = '/home/node/.n8n/obsidian/.historial.json';
const historialesDir = '/home/node/.n8n/obsidian/Historiales';

try {
  // Leer historial actual
  const historial = JSON.parse(fs.readFileSync(historialPath, 'utf8'));

  if (historial.length > 0) {
    // Guardar con fecha de hoy
    const fecha = new Date().toISOString().split('T')[0];
    fs.writeFileSync(
      path.join(historialesDir, `${fecha}.json`),
      JSON.stringify(historial)
    );

    // Limpiar historial actual
    fs.writeFileSync(historialPath, JSON.stringify([]));
  }
} catch(e) {}

return [{ json: { ok: true } }];

